<script setup>
import {computed,ref,nextTick,onMounted,onUnmounted} from 'vue'
import {request,csrf} from './client'
import TeacherSignupLayout from './TeacherSignupLayout.vue'
import VerificationLayout from './VerificationLayout.vue'
import {ArrowLeft,ArrowRight} from 'lucide-vue-next'
const props=defineProps({policy:Object,googleSession:Boolean});const emit=defineEmits(['back','verified'])
const form=ref({kind:'Student',first_name:'',last_name:'',email:'',phone:'',username:'',country:'',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,grade:'',subject:'',organization:'',job:'',backup_name:'',backup_email:'',website:'',qualifications:'',bio:'',privacy_accepted:false})
const teacherSignup=computed(()=>['Individual Teacher','Institute Teacher'].includes(form.value.kind)&&!props.googleSession)
const instituteSignup=computed(()=>form.value.kind==='Institute'&&!props.googleSession)
const providerSignup=computed(()=>teacherSignup.value||instituteSignup.value)
const extra=computed(()=>form.value.kind==='Student'?['grade']:['Individual Teacher','Institute Teacher'].includes(form.value.kind)?['subject']:['organization','job','backup_name','backup_email'])
const required=computed(()=>['first_name','last_name','email','phone','username','country','timezone',...extra.value])
const label=f=>({first_name:'First name',last_name:'Last name',backup_email:'Recovery contact email',backup_name:'Recovery contact name',job:'Your position',grade:'Grade / study level',subject:'Subject / expertise',organization:'Institute name'}[f]||f.replaceAll('_',' ').replace(/^./,s=>s.toUpperCase()))
const feedback=ref(null),status=ref('')
const cooldownKey='sisu-verification-5m-retry-until'
const now=ref(Date.now()),retryUntil=ref(0)
try{const saved=Number(sessionStorage.getItem(cooldownKey));if(saved>now.value&&saved<now.value+7200000)retryUntil.value=saved}catch{}
const remaining=computed(()=>Math.max(0,Math.ceil((retryUntil.value-now.value)/1000)))
const countdown=computed(()=>`${String(Math.floor(remaining.value/60)).padStart(2,'0')}:${String(remaining.value%60).padStart(2,'0')}`)
const timer=setInterval(()=>{now.value=Date.now()},1000)
onUnmounted(()=>clearInterval(timer))
function cooldown(seconds){retryUntil.value=Date.now()+seconds*1000;now.value=Date.now();try{sessionStorage.setItem(cooldownKey,String(retryUntil.value))}catch{}}
const token=ref(''),emailCode=ref(''),phoneCode=ref(''),emailOK=ref(false),phoneOK=ref(false),phoneSent=ref(false),password=ref(''),confirmation=ref(''),busy=ref(false),error=ref(''),done=ref(false)
const creationReady=computed(()=>emailOK.value&&(providerSignup.value||phoneOK.value))
const saveHint=computed(()=>!emailOK.value?'Verify your email to continue.':!providerSignup.value&&!phoneOK.value?'Verify your mobile number to continue.':password.value.length<12?'Email verified. Choose a password of at least 12 characters.':password.value!==confirmation.value?'Email verified. Your two passwords must match.':'Email verified. Your passwords match — ready to save.');
function google(){sessionStorage.setItem('sisu_signup_role',form.value.kind);run(async()=>{const r=await request('portal_policy','google_start',{signup:1});const u=new URL(r.url);if(u.protocol!=='https:'||u.hostname!=='accounts.google.com')throw Error('Google sign-in unavailable');location.assign(u.href)})}
{const role=sessionStorage.getItem('sisu_signup_role');if(!props.googleSession&&['Student','Individual Teacher','Institute Teacher','Institute'].includes(role))form.value.kind=role}
async function reveal(){await nextTick();feedback.value?.scrollIntoView({behavior:'smooth',block:'center'});feedback.value?.focus({preventScroll:true})}
function invalid(event){error.value='Please complete '+(event.target.getAttribute('aria-label')||'the highlighted required field')+'. '+event.target.validationMessage;reveal()}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';status.value='Working…';try{await fn()}catch(e){if(e.retryAfterSeconds){cooldown(e.retryAfterSeconds);error.value='';status.value=''}else{error.value=e.message==='Account details are unavailable. Sign in if you already registered.'?'These account details cannot be used for a new account. If you already registered, use Sign in here or Reset password above. For a new account, use a different email and an unused username.':e.message;status.value=''}}finally{busy.value=false;reveal()}}
function start(){run(async()=>{const r=await request('registration','self_start',{data:{...form.value,teaching_path:form.value.kind==='Institute Teacher'?'institute':'individual',kind:form.value.kind==='Institute Teacher'?'Individual Teacher':form.value.kind,privacy_policy_version:props.policy.privacy_policy_version}});token.value=r.challenge;status.value='Email code requested. Check your inbox and enter it below.'})}
function verify(channel){run(async()=>{await request('registration','self_verify',{token:token.value,channel,code:channel==='email'?emailCode.value:phoneCode.value});if(channel==='email')emailOK.value=true;else phoneOK.value=true;status.value=channel==='email'?(providerSignup.value?'Email verified. Create your password next.':'Email verified. Request your phone code next.'):'Phone verified. Set your password and save.'})}
function phone(){run(async()=>{await request('registration','self_phone',{token:token.value});phoneSent.value=true;status.value='Phone code requested. Enter the SMS code below.'})}
function save(){run(async()=>{await request('registration','self_complete',{token:token.value,password:password.value,confirmation:confirmation.value});password.value='';confirmation.value='';if(props.googleSession){const out=await fetch('/api/method/logout',{method:'POST',credentials:'same-origin',headers:{'X-Frappe-CSRF-Token':csrf()}});if(!out.ok)throw Error('Your account is saved. Sign out, then sign in again.')}done.value=true;status.value='Account created successfully. You can now log in.'})}
function reset(){token.value='';emailOK.value=false;phoneOK.value=false;phoneSent.value=false;emailCode.value='';phoneCode.value='';password.value='';confirmation.value=''}
onMounted(()=>{if(props.googleSession)run(async()=>{const d=await request('registration','self_google_details',{},'GET');Object.assign(form.value,d,{kind:'Student'});status.value='Google details filled in. Complete the remaining required fields.'})})
</script>
<template>
<VerificationLayout v-if="token&&!googleSession&&!done" @back="emit('back')">
  <h1>{{!emailOK?'A little check, just for you.':!phoneOK&&!providerSignup?'Let’s make this space yours.':'Your next chapter is ready.'}}</h1>
  <p class="verification-intro">{{!emailOK?'Enter the code sent to your application email. You can resend the code or change the address.':!phoneOK&&!providerSignup?'Verify your mobile number to continue.':'Choose your password to finish setting up your account.'}}</p>
  <form v-if="!emailOK" @submit.prevent="verify('email')">
    <label>Email verification code<input v-model="emailCode" aria-label="Six-digit email code" inputmode="numeric" maxlength="6" autocomplete="one-time-code" placeholder="Six-digit code"></label>
    <button class="teacher-submit" :disabled="busy||emailCode.length!==6">{{busy?'Verifying…':'Verify email & continue'}}<ArrowRight :size="16" aria-hidden="true"/></button>
    <div class="verification-actions"><button type="button" :disabled="busy||remaining>0" @click="start">Resend email code</button><button type="button" :disabled="busy" @click="reset">Change email / edit details</button></div>
  </form>
  <template v-else-if="!phoneOK&&!providerSignup">
    <form @submit.prevent="phone">
      <label>Mobile number<input :value="form.phone" type="tel" readonly autocomplete="tel" placeholder="+94"></label>
      <button class="teacher-submit" :disabled="busy||remaining>0||!emailOK">{{busy?'Sending…':phoneSent?'Resend verification code':'Send verification code'}}<ArrowRight :size="16" aria-hidden="true"/></button>
    </form>
    <form class="verification-phone-form" @submit.prevent="verify('phone')">
      <label>Verification code<input v-model="phoneCode" aria-label="Six-digit phone code" :disabled="!phoneSent||busy" inputmode="numeric" maxlength="6" autocomplete="one-time-code" placeholder="Six-digit code"></label>
      <button class="teacher-submit verification-secondary" :disabled="busy||!phoneSent||phoneCode.length!==6">Verify number<ArrowRight :size="16" aria-hidden="true"/></button>
    </form>
    <div class="verification-actions"><button type="button" :disabled="busy" @click="reset">Change number / edit details</button></div>
  </template>
  <form v-else @invalid.capture="invalid" @submit.prevent="save">
    <label>Password · Required<input v-model="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label>
    <label>Confirm password · Required<input v-model="confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label>
    <p class="verification-intro" role="status">{{saveHint}}</p>
    <button class="teacher-submit" :disabled="busy||!creationReady||(password.length<12||password!==confirmation)">Save and create account<ArrowRight :size="16" aria-hidden="true"/></button>
    <div class="verification-actions"><button type="button" :disabled="busy" @click="reset">Edit details / start again</button></div>
  </form>
  <div ref="feedback" tabindex="-1" aria-live="polite" class="verification-feedback">
    <p v-if="remaining" role="status">You’ve reached the code request limit. Try again in <strong>{{countdown}}</strong>. You can still verify a code you already received.</p>
    <p v-else-if="retryUntil">00:00 — You can request a code again.</p>
    <p v-if="error" role="alert" class="error">{{error}}</p><p v-else-if="busy" role="status">{{status}}</p>
  </div>
</VerificationLayout>
<TeacherSignupLayout v-else :active="providerSignup" :institute="instituteSignup"><main class="verified-signup" :class="{'teacher-signup-form':providerSignup,'institute-signup-form':instituteSignup}"><button type="button" :class="{'teacher-signup-back':providerSignup}" @click="emit('back')"><template v-if="providerSignup"><ArrowLeft :size="13" aria-hidden="true"/>Back to sign in</template><template v-else>← Back to sign in</template></button><h1>{{providerSignup?'Tell us your story.':'Create your SISU account'}}</h1><p v-if="providerSignup" class="teacher-signup-intro">{{instituteSignup?'Apply for your institute or school workspace.':'Apply for your teacher account.'}}</p><button v-if="!providerSignup&&!googleSession&&!token&&!done" type="button" class="google-signup" :disabled="busy||!policy.google_available" @click="google"><img :src="'/assets/frappe/icons/social/google.svg'" alt="" width="22" height="22"/> Sign up with Google</button><p v-if="!providerSignup&&!googleSession&&!policy.google_available" class="google-note">Google signup is not available yet. You can create your account using email below.</p><p v-if="googleSession">Google sign-in completed. Confirm your email and mobile number, then save your profile. Choose and confirm your password. After saving, you’ll return to the sign-in page.</p><div ref="feedback" tabindex="-1" aria-live="polite" class="signup-feedback"><p v-if="remaining" class="cooldown" role="status">You’ve reached the code request limit. Try again in <strong>{{countdown}}</strong>. You can still verify a code you already received.</p><p v-else-if="retryUntil" class="cooldown">00:00 — You can request a code again.</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-else-if="status" class="verification-notice" role="status">{{status}}</p></div><section v-if="done" role="status"><h2>Account created successfully</h2><p>Your details have been saved. Please sign in with your email and password.</p><button class="button primary" @click="emit('back')">Back to login</button></section><form v-else @invalid.capture="invalid" @submit.prevent="token?save():start()"><fieldset :disabled="busy||!!token"><label v-if="googleSession">Account type<input value="Student" readonly aria-readonly="true"></label><label v-else-if="!providerSignup">Account type · Required<select v-model="form.kind"><option>Student</option><option>Individual Teacher</option><option>Institute Teacher</option><option value="Institute">Institute admin</option></select></label><template v-if="teacherSignup">
  <div class="teacher-field-group" role="group" aria-labelledby="teacher-name-label"><span id="teacher-name-label">Your full name</span><div class="teacher-paired-fields">
    <label><span class="teacher-sr-only">First name</span><input v-model="form.first_name" aria-label="First name" required maxlength="60" placeholder="First name" autocomplete="given-name"></label>
    <label><span class="teacher-sr-only">Last name</span><input v-model="form.last_name" aria-label="Last name" required maxlength="60" placeholder="Last name" autocomplete="family-name"></label>
  </div></div>
  <label>Email<input v-model="form.email" aria-label="Email" type="email" required maxlength="254" placeholder="teacher@example.com" autocomplete="email"></label>
  <label>Preferred username<input v-model="form.username" aria-label="Username" required maxlength="60" pattern="[a-z][a-z0-9_]{2,29}" title="Use 3–30 lowercase letters, digits or underscores; start with a letter." placeholder="Choose a username" autocomplete="username"></label>
  <label>Phone number<input v-model="form.phone" aria-label="Phone" type="tel" required maxlength="254" placeholder="+94" autocomplete="tel"></label>
  <label>Subject / expertise<input v-model="form.subject" aria-label="Subject / expertise" required maxlength="254" placeholder="e.g. Combined Mathematics"></label>
  <label>Professional qualifications<input v-model="form.qualifications" aria-label="Qualifications" maxlength="500" placeholder="Your qualifications"></label>
  <div class="teacher-field-group" role="group" aria-labelledby="teacher-location-label"><span id="teacher-location-label">Country / time zone</span><div class="teacher-paired-fields">
    <label><span class="teacher-sr-only">Country</span><input v-model="form.country" aria-label="Country" required maxlength="254" placeholder="Country" autocomplete="country-name"></label>
    <label><span class="teacher-sr-only">Timezone</span><input v-model="form.timezone" aria-label="Timezone" required maxlength="254" placeholder="e.g. Asia/Colombo"></label>
  </div></div>

</template><template v-else-if="instituteSignup">
  <label>Institute name<input v-model="form.organization" aria-label="Institute name" required maxlength="254" placeholder="Your institute" autocomplete="organization"></label>
  <div class="teacher-field-group" role="group" aria-labelledby="institute-admin-label"><span id="institute-admin-label">Administrator full name</span><div class="teacher-paired-fields">
    <label><span class="teacher-sr-only">Administrator first name</span><input v-model="form.first_name" aria-label="Administrator first name" required maxlength="60" placeholder="First name" autocomplete="given-name"></label>
    <label><span class="teacher-sr-only">Administrator last name</span><input v-model="form.last_name" aria-label="Administrator last name" required maxlength="60" placeholder="Last name" autocomplete="family-name"></label>
  </div></div>
  <label>Your role at the institute<input v-model="form.job" aria-label="Your role at the institute" required maxlength="254" placeholder="Owner, principal or administrator" autocomplete="organization-title"></label>
  <label>Email<input v-model="form.email" aria-label="Email" type="email" required maxlength="254" placeholder="institute@example.com" autocomplete="email"></label>
  <label>Phone number<input v-model="form.phone" aria-label="Phone number" type="tel" required maxlength="254" placeholder="+94" autocomplete="tel"></label>
  <label>Recovery contact name<input v-model="form.backup_name" aria-label="Recovery contact name" required maxlength="60" placeholder="Enter contact name"></label>
  <label>Recovery contact email<input v-model="form.backup_email" aria-label="Recovery contact email" type="email" required maxlength="254" placeholder="recovery@example.com"></label>
  <label>Preferred username<input v-model="form.username" aria-label="Username" required maxlength="60" pattern="[a-z][a-z0-9_]{2,29}" title="Use 3–30 lowercase letters, digits or underscores; start with a letter." placeholder="Choose a username" autocomplete="username"></label>
  <div class="teacher-field-group" role="group" aria-labelledby="institute-location-label"><span id="institute-location-label">Country / time zone</span><div class="teacher-paired-fields">
    <label><span class="teacher-sr-only">Country</span><input v-model="form.country" aria-label="Country" required maxlength="254" placeholder="Country" autocomplete="country-name"></label>
    <label><span class="teacher-sr-only">Timezone</span><input v-model="form.timezone" aria-label="Timezone" required maxlength="254" placeholder="e.g. Asia/Colombo"></label>
  </div></div>
</template><div v-else class="signup-grid"><label v-for="field in required" :key="field">{{label(field)}} · Required<input v-model="form[field]" :aria-label="label(field)" :readonly="googleSession&&field==='email'" :type="field.includes('email')?'email':field==='phone'?'tel':'text'" required :maxlength="field.includes('name')?60:254" :pattern="field==='username'?'[a-z][a-z0-9_]{2,29}':undefined" :title="field==='username'?'Use 3–30 lowercase letters, digits or underscores; start with a letter.':undefined" :placeholder="field==='phone'?'+94761234567':field==='username'?'e.g. sisu_student':''"/></label><p class="phone-help">Sri Lankan mobile: use +94 and omit the first 0. For example, 0761234567 → +94761234567. Use a mobile number you can receive verification codes on.</p><label v-for="field in ['website','qualifications','bio']" :key="field">{{label(field)}} · Optional<input v-model="form[field]" :aria-label="label(field)" :readonly="googleSession&&field==='email'" :type="field==='website'?'url':'text'" maxlength="500"/></label></div><label class="consent" :class="{'teacher-consent':providerSignup}"><input type="checkbox" v-model="form.privacy_accepted" aria-label="privacy policy acceptance" required/>I accept the <a :href="policy.privacy_policy_url" target="_blank" rel="noopener noreferrer">privacy policy</a>.</label></fieldset><p v-if="form.kind!=='Student'&&!providerSignup">Your teaching workspace stays locked until your plan payment is verified. Account verification does not grant a provider endorsement badge.</p><button v-if="!token" class="button primary" :class="{'teacher-submit':providerSignup}" :disabled="busy||remaining>0||!policy.privacy_policy_url">{{busy?'Sending…':providerSignup?'Verify email & continue':'Send email verification code'}}<ArrowRight v-if="providerSignup" :size="16" aria-hidden="true"/></button><p v-if="teacherSignup" class="teacher-help">Your teaching workspace stays locked until your plan payment is verified. Account verification does not grant a provider endorsement badge.</p><p v-if="providerSignup&&!policy.privacy_policy_url" class="teacher-help">Signup will be available once the site’s privacy policy is published.</p><fieldset v-if="providerSignup" :disabled="busy||!!token">  <details class="teacher-extra-options"><summary>More signup options</summary>
    <p v-if="instituteSignup" class="teacher-help">Your teaching workspace stays locked until your plan payment is verified. Account verification does not grant a provider endorsement badge.</p>
    <p class="teacher-help">Sri Lankan mobile: use +94 and omit the first 0. For example, 0761234567 → +94761234567. Use a mobile number you can receive verification codes on.</p>
    <label>Website · Optional<input v-model="form.website" aria-label="Website" type="url" maxlength="500"></label>
    <label v-if="instituteSignup">Qualifications · Optional<input v-model="form.qualifications" aria-label="Qualifications" maxlength="500"></label>
    <label>Bio · Optional<input v-model="form.bio" aria-label="Bio" maxlength="500"></label>
    <label>Account type · Required<select v-model="form.kind"><option>Student</option><option>Individual Teacher</option><option>Institute Teacher</option><option value="Institute">Institute admin</option></select></label>
    <button v-if="!token&&!done" type="button" class="google-signup" :disabled="busy||!policy.google_available" @click="google">Sign up with Google</button>
    <p v-if="!policy.google_available" class="teacher-help">Google signup is not available yet. You can create your account using email above.</p>
  </details></fieldset><template v-if="token"><button type="button" :disabled="busy" @click="reset">Edit details / start again</button><section><h2>Email verification {{emailOK?'✓':''}}</h2><label v-if="!emailOK">Six-digit email code<input v-model="emailCode" inputmode="numeric" maxlength="6" autocomplete="one-time-code"/></label><button v-if="!emailOK" type="button" :disabled="busy||emailCode.length!==6" @click="verify('email')">Verify email</button></section><section><h2>Phone verification {{phoneOK?'✓':''}}</h2><button v-if="!phoneOK" type="button" :disabled="busy||remaining>0||!emailOK" @click="phone">{{phoneSent?'Resend phone code':'Send phone code'}}</button><label v-if="phoneSent&&!phoneOK">Six-digit phone code<input v-model="phoneCode" inputmode="numeric" maxlength="6" autocomplete="one-time-code"/></label><button v-if="phoneSent&&!phoneOK" type="button" :disabled="busy||phoneCode.length!==6" @click="verify('phone')">Verify phone</button></section><label>Password · Required<input v-model="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required/></label><label>Confirm password · Required<input v-model="confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="128" required/></label><p class="save-readiness" role="status">{{saveHint}}</p><button class="button primary" :disabled="busy||!creationReady||(password.length<12||password!==confirmation)">{{googleSession?'Save and verify account':'Save and create account'}}</button></template></form></main></TeacherSignupLayout></template>
<style scoped>.verification-notice,.save-readiness{padding:14px 18px;border:1px solid #cddfd4;border-radius:14px;background:#eff8f2;color:#24543b;line-height:1.6}.save-readiness{background:#f5f2fc;border-color:#ded5ee;color:#49335f}.verified-signup{max-width:820px;margin:35px auto;padding:28px;background:var(--surface,#fff);border-radius:20px}.verified-signup fieldset{border:0;padding:0}.signup-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.verified-signup label{display:grid;gap:8px;margin:14px 0}.verified-signup input,.verified-signup select{padding:12px;border:1px solid #b9b3c6;border-radius:8px;width:100%;box-sizing:border-box}.verified-signup .consent{display:flex;align-items:center}.consent input{width:auto}.verified-signup button{margin:8px 8px 8px 0;padding:10px 15px}.verified-signup button{min-height:44px;border:1px solid #c4bbd5;border-radius:10px;background:#f5f1fa;color:#38224e;font:600 15px/1.4 system-ui;cursor:pointer}.verified-signup button:disabled{opacity:.55;cursor:not-allowed}.verified-signup button.primary{background:#592b91;color:white;border-color:#592b91}.verified-signup .google-signup{display:flex;align-items:center;justify-content:center;gap:12px;width:100%;padding:14px 20px;background:#fff;border:1px solid #b9b3c6;box-shadow:0 2px 5px #24113712}.google-mark{font:700 22px system-ui;color:#4285f4}.google-note{font-size:14px;color:#64566f}.signup-feedback:focus{outline:2px solid #7652a2;outline-offset:5px}.verified-signup section{margin:22px 0}@media(max-width:600px){.signup-grid{grid-template-columns:1fr}}.signup-feedback:has(.cooldown){position:sticky;top:0;z-index:2;background:var(--surface,#fff)}.cooldown{padding:16px;border:1px solid #d8cfe7;border-radius:12px;background:#f6f3fc;color:#49335f}.cooldown strong{font-variant-numeric:tabular-nums}</style>
